def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    queries=inputs.get('queries',[])
    observed={}
    raw_answers=inputs.get('semantic_answers',[])
    if isinstance(raw_answers,list):
        for a in raw_answers:
            if isinstance(a,dict) and a.get('id') is not None:
                observed[a.get('id')]=a
    by_id={}
    for s in spans:
        by_id[s.get('id')]=s
    corrections=[]
    for q in queries:
        if q.get('operation')!='disposal_retention_clause_role':
            continue
        qid=q.get('id')
        if qid not in observed:
            continue
        unit_ids=q.get('unit_ids',[])
        if not unit_ids:
            continue
        focus=by_id.get(unit_ids[len(unit_ids)-1])
        if focus is None:
            continue
        quote=focus.get('text','')
        if not isinstance(quote,str):
            quote=str(quote)
        t=quote.casefold().strip()
        choice=None
        if (('continue to be bound' in t or 'shall continue to apply' in t or 'obligation' in t and 'continue to apply' in t) and ('return' in t or 'retained' in t)):
            choice='no_relevant_operative_effect'
        elif len(t)<120 and 'confidential information' in t and ('return' in t or 'destruction' in t) and not any_phrase(t,[' shall ',' must ',' agrees ',' may retain','may certify']):
            choice='no_relevant_operative_effect'
        elif re.search(r'\bno\s+(?:copies?|copy)[\s\S]{0,120}\bretain(?:ed|ing)?\b',t,re.I) is not None or re.search(r'\bshall\s+not\s+be\s+retained\b',t,re.I) is not None:
            choice='operative_retention_prohibition'
        elif 'backup system' in t and 'destroy' in t and ('retention process' in t or 'records retention' in t):
            choice='supplemental_linked_effect'
        elif t.startswith('in such an instance') and 'retained' in t and ('return' in t or 'destroy' in t):
            choice='supplemental_linked_effect'
        elif 'may retain' in t:
            if re.search(r'\b(?:shall|must|agrees?|required)\b[\s\S]{0,180}\b(?:return|destroy)',t,re.I) is not None:
                choice='operative_disposal_and_retention_permission'
            else:
                choice='operative_retention_permission'
        elif t.startswith('in lieu of return') and 'destroy' in t:
            choice='operative_disposal'
        elif re.search(r'\b(?:shall|must|agrees?|required)\b[\s\S]{0,220}\b(?:return(?:ed|ing)?|destroy(?:ed|ing)?)\b',t,re.I) is not None:
            choice='operative_disposal'
        if choice is None:
            continue
        if observed[qid].get('choice')==choice:
            continue
        corrections.append({'id':qid,'choice':choice,'evidence':[{'unit_id':focus.get('id'),'quote':quote}]})
    return {'corrections':corrections}

