def _sr_window_ids(spans,i):
    ids=[]
    raw=_sr_text(spans[i])
    t=raw.casefold().strip()
    if i>0 and (re.search(r'\bforegoing\b',raw,re.I) is not None or _sr_heading(_sr_text(spans[i-1]))):
        ids.append(spans[i-1].get('id'))
    linked=False
    if t.startswith('in such an instance'):
        j=i-1
        stop=i-5
        while j>=0 and j>=stop:
            prior=_sr_text(spans[j]).casefold()
            if 'may retain' in prior and ('required' in prior or 'applicable law' in prior):
                x=spans[j].get('id')
                if x not in ids:
                    ids.append(x)
                linked=True
                break
            j-=1
    if _sr_linked(raw) and not linked:
        j=i-1
        stop=i-5
        while j>=0 and j>=stop:
            if _sr_principal(_sr_text(spans[j])):
                if j>0 and _sr_heading(_sr_text(spans[j-1])):
                    x=spans[j-1].get('id')
                    if x not in ids:
                        ids.append(x)
                x=spans[j].get('id')
                if x not in ids:
                    ids.append(x)
                break
            j-=1
    x=spans[i].get('id')
    if x not in ids:
        ids.append(x)
    return ids

def _sr_add(out,term,ids):
    def merged_ids(a,b):
        z=[]
        for x in a+b:
            if x is not None and x not in z:
                z.append(x)
        return z
    def ex_items(x):
        if x==['no_exceptions']:
            return []
        if isinstance(x,list) and x:
            if x[0]=='exception_set' and len(x)>1:
                return [x[1]]
            if x[0]=='add_exception' and len(x)>2:
                return ex_items(x[1])+[x[2]]
        return []
    def pack_ex(xs):
        ys=[]
        for x in xs:
            if x not in ys:
                ys.append(x)
        if not ys:
            return ['no_exceptions']
        v=['exception_set',ys[0]]
        i=1
        while i<len(ys):
            v=['add_exception',v,ys[i]]
            i+=1
        return v
    def contains(x,wanted):
        if x==wanted:
            return True
        if isinstance(x,list):
            for y in x[1:]:
                if isinstance(y,list) and contains(y,wanted):
                    return True
        return False
    if isinstance(term,list) and term and term[0]=='retention_permission' and len(term)==5:
        ractor=term[1]
        rinfo=term[2]
        rcond=term[4]
        rex=['retention_exception',ractor,rinfo,rcond]
        for s in out:
            old=s.get('term')
            if isinstance(old,list) and len(old)==5 and old[0]=='disposal_obligation' and contains(old[1],ractor):
                old[4]=pack_ex(ex_items(old[4])+[rex])
                s['support_ids']=merged_ids(s.get('support_ids',[]),ids)
    if isinstance(term,list) and len(term)==5 and term[0]=='disposal_obligation':
        for s in out:
            old=s.get('term')
            if not (isinstance(old,list) and len(old)==5 and old[0]=='disposal_obligation'):
                continue
            if old[1]!=term[1] or old[3]!=term[3]:
                continue
            oa=old[2]
            na=term[2]
            if oa==na:
                old[4]=pack_ex(ex_items(old[4])+ex_items(term[4]))
                s['support_ids']=merged_ids(s.get('support_ids',[]),ids)
                return
            if isinstance(oa,list) and oa and oa[0]=='return_to' and isinstance(na,list) and na and na[0]=='action_alternative' and contains(na,['return_to',na[1][1],['disclosing_party']]):
                info=oa[1]
                old[2]=['action_alternative',oa,['destroy',info]]
                old[4]=pack_ex(ex_items(old[4])+ex_items(term[4]))
                s['support_ids']=merged_ids(s.get('support_ids',[]),ids)
                return
            if isinstance(na,list) and na and na[0]=='return_to' and isinstance(oa,list) and oa and oa[0]=='action_alternative':
                s['support_ids']=merged_ids(s.get('support_ids',[]),ids)
                old[4]=pack_ex(ex_items(old[4])+ex_items(term[4]))
                return
    for s in out:
        if s.get('term')==term:
            s['support_ids']=merged_ids(s.get('support_ids',[]),ids)
            return
    out.append({'term':term,'support_ids':merged_ids([],ids)})
